const client = createClient();

async function claim(key, ttlMs) {
  const ok = await client.set(`seen:${key}`, '1', { NX: true, PX: ttlMs });
  return ok === 'OK';                          // null => already claimed
}

async function onMessage(msg) {
  if (!(await claim(msg.key, REDELIVERY_WINDOW_MS))) return ack(msg);
  await applyEffects(msg);
  await ack(msg);
}
